import { parseDecimal, formatParts, normalize } from './decimal.mjs';

export const MODES = Object.freeze(['halfEven', 'halfUp', 'halfDown', 'up', 'down', 'ceiling', 'floor']);

function increment(s) {
  let i = s.length - 1;
  while (i >= 0 && s[i] === '9') i--;
